content.code:
body {
  /* List fonts in preference order; end with a generic family */
  font-family: 'Inter', 'Segoe UI', Arial, sans-serif;
}

code, pre {
  font-family: 'Fira Code', 'Consolas', 'Courier New', monospace;
}

/* Load a web font from Google Fonts */
@import url('https://fonts.googleapis.com/css2?family=Inter:wght@400;600;700&display=swap');

h1 {
  font-size: 2.5rem;    /* relative to root font size (usually 16px) */
  font-weight: 700;     /* 100–900; 400 = normal, 700 = bold */
  font-style: normal;   /* normal | italic | oblique */
  letter-spacing: -0.02em; /* tighten display headings */
  text-transform: uppercase; /* DISPLAY HEADINGS */
}

p {
  font-size: 1rem;      /* 16px at default browser settings */
  font-weight: 400;
  line-height: 1.6;     /* unitless — 1.6 × font-size — scales correctly */
}

.hero    { text-align: center; }
.article { text-align: left; }  /* default — most readable for body text */

a {
  text-decoration: none;        /* remove underline */
  text-decoration: underline;   /* explicit underline */
}

.truncate {
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;      /* shows '...' when text overflows */
  max-width: 200px;
}

:root {
  --text-xs:   0.75rem;   /* 12px */
  --text-sm:   0.875rem;  /* 14px */
  --text-base: 1rem;      /* 16px */
  --text-lg:   1.125rem;  /* 18px */
  --text-xl:   1.25rem;   /* 20px */
  --text-2xl:  1.5rem;    /* 24px */
  --text-3xl:  1.875rem;  /* 30px */
  --text-4xl:  2.25rem;   /* 36px */
}

h1 { font-size: var(--text-4xl); font-weight: 800; }
h2 { font-size: var(--text-2xl); font-weight: 700; }
p  { font-size: var(--text-base); line-height: 1.6; }
